def transform(grid):
    from collections import Counter

    rows = len(grid)
    if rows == 0:
        return []

    cols = len(grid[0])

    # Find background color (most frequent)
    count = Counter()
    for r in range(rows):
        for c in range(cols):
            count[grid[r][c]] += 1
    bg = count.most_common(1)[0][0]

    # Find rows and columns that have non-background content
    row_has_content = [False] * rows
    col_has_content = [False] * cols

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                row_has_content[r] = True
                col_has_content[c] = True

    # Build output grid
    result = []
    for r in range(rows):
        row_data = []
        for c in range(cols):
            if col_has_content[c]:
                row_data.append(grid[r][c])
        # Fill remaining positions with 0 (not bg)
        len_row = len(result[0]) if result else 0
        while len(row_data) < len(result[0]):
            row_data.append(0)
        # Trim to correct length if needed
        while len(row_data) > cols:
            row_data = row_data[:cols]
        result.append(row_data)

    # Convert background cells to 0 in output
    new_bg = 0
    for r in range(len(result)):
        for c in range(len(result[r])):
            if result[r][c] == bg:
                result[r][c] = 0

    return result
